{

    internal InnerCampaignTelephonyOutboundModeFactory OutboundModeFactory { get; set; }

    internal InnerCampaignTelephonyOutboundConfigFactory DefaultOutboundConfigFactory { get; set; }

    protected override Humidifier.ConnectCampaignsV2.CampaignTypes.TelephonyChannelSubtypeConfig Create()
    {
        var telephonyChannelSubtypeConfigResult = CreateTelephonyChannelSubtypeConfig();
        factoryAction?.Invoke(telephonyChannelSubtypeConfigResult);

        return telephonyChannelSubtypeConfigResult;
    }

    private Humidifier.ConnectCampaignsV2.CampaignTypes.TelephonyChannelSubtypeConfig CreateTelephonyChannelSubtypeConfig()
    {
        var telephonyChannelSubtypeConfigResult = new Humidifier.ConnectCampaignsV2.CampaignTypes.TelephonyChannelSubtypeConfig();

        return telephonyChannelSubtypeConfigResult;
    }
    public override void CreateChildren(Humidifier.ConnectCampaignsV2.CampaignTypes.TelephonyChannelSubtypeConfig result)
    {
        base.CreateChildren(result);

        result.OutboundMode ??= OutboundModeFactory?.Build();
        result.DefaultOutboundConfig ??= DefaultOutboundConfigFactory?.Build();
    }

} // End Of Class

